for rec in records:
    if rec.x_signed_attachment_id:
        signed_on = rec.x_signed_on or datetime.datetime.now()

        rec.sudo().write({
            'x_document_state': 'signed',
            'x_signed_on': signed_on,
        })

        registry_model = env['x_hr.recruitment_document'].sudo()

        registry_doc = False

        if rec.x_pdf_attachment_id:
            registry_doc = registry_model.search([
                ('x_document_type', '=', 'interview_evaluation'),
                ('x_source_model', '=', 'x_hr.applicant_mcep_interview'),
                ('x_source_res_id', '=', rec.id),
                ('x_generated_attachment_id', '=', rec.x_pdf_attachment_id.id),
            ], order='id desc', limit=1)

        if not registry_doc:
            registry_doc = registry_model.search([
                ('x_document_type', '=', 'interview_evaluation'),
                ('x_source_model', '=', 'x_hr.applicant_mcep_interview'),
                ('x_source_res_id', '=', rec.id),
                ('x_signature_mode', '=', 'native_sign'),
                ('x_sign_request_res_id', '!=', False),
            ], order='id desc', limit=1)

        if not registry_doc:
            registry_doc = registry_model.search([
                ('x_document_type', '=', 'interview_evaluation'),
                ('x_source_model', '=', 'x_hr.applicant_mcep_interview'),
                ('x_source_res_id', '=', rec.id),
            ], order='id desc', limit=1)

        if not registry_doc and rec.x_applicant_id:
            registry_doc = registry_model.search([
                ('x_document_type', '=', 'interview_evaluation'),
                ('x_applicant_id', '=', rec.x_applicant_id.id),
                ('x_generated_attachment_id', '=', rec.x_pdf_attachment_id.id if rec.x_pdf_attachment_id else False),
            ], order='id desc', limit=1)

        if not registry_doc and rec.x_applicant_id:
            registry_doc = registry_model.search([
                ('x_document_type', '=', 'interview_evaluation'),
                ('x_applicant_id', '=', rec.x_applicant_id.id),
            ], order='id desc', limit=1)

        if registry_doc:
            registry_doc.write({
                'x_state': 'signed',
                'x_signed_attachment_id': rec.x_signed_attachment_id.id,
                'x_signed_on': signed_on,
                'x_responsible_user_id': env.user.id,
                'x_source_model': 'x_hr.applicant_mcep_interview',
                'x_source_res_id': rec.id,
                'x_notes': 'Signed F-0002 Interview Evaluation PDF linked manually. Registry marked signed from the interview signed attachment field.',
            })
        elif rec.x_applicant_id:
            registry_model.create({
                'x_name': 'Interview Evaluation - %s - v1' % (
                    rec.x_full_name_snapshot or rec.x_applicant_id.partner_name or rec.x_applicant_id.name or rec.display_name,
                ),
                'x_applicant_id': rec.x_applicant_id.id,
                'x_document_type': 'interview_evaluation',
                'x_state': 'signed',
                'x_generated_attachment_id': rec.x_pdf_attachment_id.id if rec.x_pdf_attachment_id else False,
                'x_signed_attachment_id': rec.x_signed_attachment_id.id,
                'x_version': 1,
                'x_generated_on': rec.x_generated_on or signed_on,
                'x_sent_on': rec.x_sent_on or signed_on,
                'x_signed_on': signed_on,
                'x_responsible_user_id': env.user.id,
                'x_source_model': 'x_hr.applicant_mcep_interview',
                'x_source_res_id': rec.id,
                'x_notes': 'Interview registry row was created during signed attachment linking because no registry row was found.',
            })

        rec.message_post(body='Signed F-0002 Interview Evaluation PDF linked. Interview record and recruitment document registry marked as signed.')
        if rec.x_applicant_id:
            rec.x_applicant_id.message_post(body='Signed F-0002 Interview Evaluation PDF linked. Recruitment document registry marked as signed.')
